// One icon list: src/native/lucide.ts is generated from src/lucide.ts (same
// names, lucide-react-native components, the native createIcon). Run by `build`.
import { readFileSync, writeFileSync } from 'node:fs';

const web = readFileSync(new URL('../src/lucide.ts', import.meta.url), 'utf8');
const native =
  '// Generated by scripts/gen-native.mjs from src/lucide.ts. Do not edit.\n' +
  web.replace("from 'lucide-react';", "from 'lucide-react-native';");

writeFileSync(new URL('../src/native/lucide.ts', import.meta.url), native);
